// Cuatro salidas: ESP32, MyMQTT, registro JSONL y persistencia MySQL.
const prefix = env.get('MQTT_PREFIX') || 'powershare/esp32-01';
const now = Date.now();
const state = context.get('gateway') || {online: false, connected: false, lastTelemetry: 0, pending: Object.create(null)};
const out = [[], [], [], []];
const sendApp = (kind, payload, retain = false) => out[1].push({topic: `${prefix}/app/${kind}`, payload: typeof payload === 'string' ? payload : JSON.stringify(payload), qos: kind === 'telemetry' ? 0 : 1, retain});
const history = (kind, payload, topic = msg.topic || `${prefix}/app/status`) => out[3].push({payload: {receivedAt: new Date(now).toISOString(), kind, topic, payload}});
const log = (kind, payload) => { out[2].push({payload: JSON.stringify({receivedAt: new Date(now).toISOString(), kind, payload})}); history(kind, payload); };
const reject = (id, reason) => { const ack = {id, result: 'rejected', reason, source: 'nodered'}; sendApp('ack', ack); log('ack', ack); };
const text = Buffer.isBuffer(msg.payload) ? msg.payload.toString() : msg.payload;
let data = text;
if (typeof text === 'string' && !['online', 'offline'].includes(text)) {
    try { data = JSON.parse(text); } catch { data = null; }
}
if (msg.status) {
    state.connected = msg.status.fill === 'green';
    if (!state.connected) { state.online = false; state.lastTelemetry = 0; }
} else if (msg.topic === '__tick') {
    for (const [id, pending] of Object.entries(state.pending)) {
        if (now - pending.sentAt >= 5000) {
            const ack = {id, result: 'unknown', reason: 'ack_timeout', source: 'nodered'};
            sendApp('ack', ack); log('ack', ack); delete state.pending[id];
        }
    }
} else if (msg.topic === `${prefix}/app/commands`) {
    history('command', data ?? {raw: text});
    const id = data && typeof data.id === 'string' && /^[A-Za-z0-9_-]{1,40}$/.test(data.id) ? data.id : null;
    const keys = data && typeof data === 'object' && !Array.isArray(data) ? Object.keys(data) : [];
    if (msg.retain) reject(id, 'retained_command');
    else if (!id || !data || typeof data.command !== 'string' || !['c', 'a', 'f', 'd', 'h'].includes(data.command) ||
        keys.some(k => !['id', 'command', 'wh'].includes(k)) ||
        (data.command === 'c' ? typeof data.wh !== 'number' || !Number.isFinite(data.wh) || data.wh <= 0 || data.wh > 3.402823466e38 : keys.includes('wh')) ||
        Buffer.byteLength(typeof text === 'string' ? text : JSON.stringify(data)) > 256) reject(id, 'invalid_format');
    else if (!state.connected || !state.online || now - state.lastTelemetry > 3000) reject(id, 'device_offline');
    else {
        const command = {id, command: data.command};
        if (data.command === 'c') command.wh = data.wh;
        const signature = JSON.stringify(command);
        const previous = state.pending[id];
        if (previous && previous.signature !== signature) reject(id, 'id_conflict');
        else if (!previous && Object.keys(state.pending).length >= 32) reject(id, 'queue_full');
        else if (!previous) {
            state.pending[id] = {signature, sentAt: now};
            out[0].push({topic: `${prefix}/device/commands`, payload: signature, qos: 1, retain: false});
        }
    }
} else if (msg.topic && msg.topic.startsWith(`${prefix}/device/`)) {
    const kind = msg.topic.slice(`${prefix}/device/`.length);
    if (kind === 'status' && ['online', 'offline'].includes(text)) {
        history('status', {status: text});
        state.online = text === 'online';
        if (!state.online) state.lastTelemetry = 0;
    } else if (kind === 'telemetry' && !msg.retain && data &&
        ['DISPONIBLE', 'ACTIVO', 'DESHABILITADO', 'ENFRIAMIENTO'].includes(data.state) &&
        ['balanceWh', 'currentA', 'temperatureC', 'coolerPwm', 'uptimeMs'].every(k => typeof data[k] === 'number' && Number.isFinite(data[k])) &&
        typeof data.loadOn === 'boolean' && typeof data.bootId === 'string') {
        state.lastTelemetry = now;
        sendApp(kind, data);
        history(kind, data);
    } else if (kind === 'ack' && !msg.retain && data && (data.id === null || typeof data.id === 'string') && ['applied', 'rejected'].includes(data.result)) {
        delete state.pending[data.id]; sendApp(kind, data); log(kind, data);
    } else if (kind === 'events' && !msg.retain && data && typeof data.event === 'string') {
        sendApp(kind, data); log(kind, data);
    } else if (kind === 'commands') history('command', data ?? {raw: text});
    else log('invalid_device_message', {topic: msg.topic});
}
// Un online retained puede sobrevivir al reinicio del broker. Exigir datos frescos.
const available = state.connected && state.online && now - state.lastTelemetry <= 3000 ? 'online' : 'offline';
if (state.reported !== available) { state.reported = available; sendApp('status', available, true); history('availability', {status: available}, `${prefix}/app/status`); }
context.set('gateway', state);
return out.map(messages => messages.length ? messages : null);

// SQL fijo y valores separados: ningun dato MQTT se interpola en la consulta.
const record = msg.payload;
if (!record || typeof record.kind !== 'string' || !record.receivedAt || !record.topic) {
    node.error('Registro historico invalido', msg);
    return null;
}
const data = record.payload;
const commandId = data && typeof data.id === 'string' && /^[A-Za-z0-9_-]{1,40}$/.test(data.id) ? data.id : null;
const bootId = data && typeof data.bootId === 'string' && /^[A-Za-z0-9_-]{1,32}$/.test(data.bootId) ? data.bootId : null;
msg.topic = 'INSERT INTO iot_history (received_at, device_prefix, kind, source_topic, command_id, boot_id, payload) VALUES (?, ?, ?, ?, ?, ?, ?)';
msg.payload = [record.receivedAt.replace('T', ' ').replace('Z', ''), env.get('MQTT_PREFIX') || 'powershare/esp32-01', record.kind, record.topic, commandId, bootId, JSON.stringify(data)];
return msg;

// Consulta manual del editor: ultimos 50 registros del dispositivo configurado.
msg.topic = 'SELECT id, received_at, kind, source_topic, command_id, boot_id, payload FROM iot_history WHERE device_prefix = ? ORDER BY received_at DESC, id DESC LIMIT 50';
msg.payload = [env.get('MQTT_PREFIX') || 'powershare/esp32-01'];
return msg;
